"use server";

import { cookies } from "next/headers";
import { refresh } from "next/cache";

const preferenceCookie = "notifications-enabled";

export async function toggleNotifications() {
  const cookieStore = await cookies();
  const enabled = cookieStore.get(preferenceCookie)?.value === "on";

  cookieStore.set(preferenceCookie, enabled ? "off" : "on", {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    maxAge: 60 * 60 * 24 * 365,
  });

  refresh();
}
import { cookies } from "next/headers";
import { toggleNotifications } from "./actions";

export default async function Home() {
  const enabled = (await cookies()).get("notifications-enabled")?.value === "on";

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are {enabled ? "on" : "off"}.</p>
      <form action={toggleNotifications}>
        <button type="submit">
          Turn notifications {enabled ? "off" : "on"}
        </button>
      </form>
    </main>
  )
}
import type { ReactNode } from "react";

export default function RootLayout({ children }: { children: ReactNode }) {
  return (
    <html lang="en">
      <body>{children}</body>
    </html>
  );
}

